using System.Diagnostics;using System.Runtime.InteropServices;using Xunit;namespace Midl.Integration.Tests;/// <summary>/// End-to-end test: builds an out-of-proc WinRT EXE server, proxy DLL, and/// client EXE, then validates that cross-process marshaling works correctly/// through our custom generated proxy/stub code./// </summary>public class E2EOutOfProcMarshalTests{    /// <summary>    /// Runs the build-and-test.ps1 script which:    /// 1. Generates proxy code from IDL via our CLI    /// 2. Compiles server EXE, proxy DLL, client EXE with MSVC    /// 3. Registers them in HKCU    /// 4. Launches the server, runs the client, validates results    /// 5. Cleans up registration    /// </summary>    [SkippableFact]    [Trait("Category", "E2E")]    public void OutOfProc_CustomMarshal_CrossProcess_RoundTrip()    {        Skip.IfNot(RuntimeInformation.IsOSPlatform(OSPlatform.Windows),            "Out-of-proc COM test requires Windows");        // Ensure MSVC is available        var vsWhere = Path.Combine(            Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),            @"Microsoft Visual Studio\Installer\vswhere.exe");        Skip.IfNot(File.Exists(vsWhere), "Visual Studio / MSVC not installed");        // Build the CLI first        var repoRoot = FindRepoRoot();        var cliProject = Path.Combine(repoRoot, "src", "Midl.Cli", "Midl.Cli.csproj");        Skip.IfNot(File.Exists(cliProject), $"CLI project not found at {cliProject}");        // CLI is already built as a dependency of this test project        // Run the build-and-test script        var scriptDir = Path.Combine(repoRoot, "tests", "e2e-custom-marshal", "outofproc");        var scriptPath = Path.Combine(scriptDir, "build-and-test.ps1");        Skip.IfNot(File.Exists(scriptPath), $"Build script not found at {scriptPath}");        var result = RunProcess(            "powershell",            $"-NoProfile -ExecutionPolicy Bypass -File \"{scriptPath}\"",            scriptDir,            timeoutMs: 120_000);        // Output all stdout/stderr for diagnostics        if (!string.IsNullOrWhiteSpace(result.StdOut))            Console.Write(result.StdOut);        if (!string.IsNullOrWhiteSpace(result.StdErr))            Console.Error.Write(result.StdErr);        Assert.Equal(0, result.ExitCode);    }    private static string FindRepoRoot()    {        var dir = AppContext.BaseDirectory;        while (dir != null)        {            if (File.Exists(Path.Combine(dir, "Midl.slnx")) ||                File.Exists(Path.Combine(dir, "Directory.Build.props")))                return dir;            dir = Path.GetDirectoryName(dir);        }        // Fallback: walk up from current directory        dir = Directory.GetCurrentDirectory();        while (dir != null)        {            if (File.Exists(Path.Combine(dir, "Midl.slnx")) ||                File.Exists(Path.Combine(dir, "Directory.Build.props")))                return dir;            dir = Path.GetDirectoryName(dir);        }        return Directory.GetCurrentDirectory();    }    private record ProcessResult(int ExitCode, string StdOut, string StdErr);    private static ProcessResult RunProcess(string fileName, string arguments, string workingDir, int timeoutMs = 30_000)    {        using var proc = new Process();        proc.StartInfo = new ProcessStartInfo        {            FileName = fileName,            Arguments = arguments,            WorkingDirectory = workingDir,            RedirectStandardOutput = true,            RedirectStandardError = true,            UseShellExecute = false,            CreateNoWindow = true,        };        proc.Start();        var stdout = proc.StandardOutput.ReadToEnd();        var stderr = proc.StandardError.ReadToEnd();        proc.WaitForExit(timeoutMs);        if (!proc.HasExited)        {            proc.Kill(entireProcessTree: true);            return new ProcessResult(-1, stdout, stderr + "\n[TIMEOUT]");        }        return new ProcessResult(proc.ExitCode, stdout, stderr);    }}